            rightBMax[b][2] = std::max(rightBMax[b][2], pmax[2]);
        }

        for (int b = 0; b <= bin; ++b) {
            leftCount[b]++;
            leftBMin[b][0] = std::min(leftBMin[b][0], pmin[0]);
            leftBMin[b][1] = std::min(leftBMin[b][1], pmin[1]);
