            leftBMax[b][2] = std::max(leftBMax[b][2], pmax[2]);
        }
    }

    for (int i = 0; i < kNumBins - 1; ++i) {
        if (leftCount[i] == 0 || rightCount[i+1] == 0) continue;

        const real3<T> &lmin = leftBMin[i];
        const real3<T> &lmax = leftBMax[i];
        const real3<T> &rmin = rightBMin[i+1];
        const real3<T> &rmax = rightBMax[i+1];

        const T leftArea = (lmax[0] - lmin[0]) * (lmax[1] - lmin[1]) * (lmax[2] - lmin[2]);
        const T rightArea = (rmax[0] - rmin[0]) * (rmax[1] - rmin[1]) * (rmax[2] - rmin[2]);
        const T parentArea = (bmax[0] - bmin[0]) * (bmax[1] - bmin[1]) * (bmax[2] - bmin[2]);

        const T cost = T(0.125) + (leftArea * leftCount[i] + rightArea * rightCount[i+1]) / parentArea;

        if (cost < bestCost) {
            bestCost = cost;
            bestAxis = axis;
            bestPos = bmin[axis] + (i + 1) * extent[axis] / kNumBins;
        }
    }
}

if (bestAxis < 0) return false;

cut_pos[0] = (bestAxis == 0) ? bestPos : T(0);
cut_pos[1] = (bestAxis == 1) ? bestPos : T(0);
cut_pos[2] = (bestAxis == 2) ? bestPos : T(0);
*minCostAxis = bestAxis;

return true;

